function renderRecognition(includeInterim=true){sessionFinalText=composeFinalText();const interimText=includeInterim?sessionResults.filter(result=>result&&!result.isFinal).map(result=>result.text).join(" "):"";transcript.value=`${baseText}${sessionFinalText}${interimText?`${sessionFinalText?" ":""}${interimText}`:""}`.trimStart();rawDraftText=`${rawBaseText}${sessionFinalText}${interimText?`${sessionFinalText?" ":""}${interimText}`:""}`.trim();reparseButton.disabled=!rawDraftText;updateSaveState()}
